package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamHumanBodyBank1 {
    private const val T = "මානව දේහ පද්ධතිවල ව්‍යුහය හා ක්‍රියාකාරිත්වය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("වැඩිහිටි මිනිස් ඇටසැකිලි පද්ධතිය තුළ අඩංගු මුළු අස්ථි සංඛ්‍යාව කීයද?", "අස්ථි 206කි", "අස්ථි 300කි", "අස්ථි 150කි", "අස්ථි 250කි", "ළදරු වියේදී අස්ථි 300කට ආසන්න සංඛ්‍යාවක් තිබුණද වැඩෙත්ම ඒවා එකිනෙක බද්ධ වී වැඩිහිටියෙකු තුළ අස්ථි 206ක් ඉතිරි වේ."),
        q("මිනිස් ඇටසැකිලි පද්ධතිය ප්‍රධාන වශයෙන් බෙදා වෙන් කරනු ලබන කොටස් දෙක මොනවාද?", "අක්ෂක ඇටසැකිල්ල සහ උපාංග ඇටසැකිල්ල", "හිස්කබල සහ පාද ඇටසැකිල්ල", "බාහිර ඇටසැකිල්ල සහ අභ්‍යන්තර ඇටසැකිල්ල", "ඉහළ කොටස සහ පහළ කොටස", "අක්ෂක ඇටසැකිල්ලට අස්ථි 80ක්ද, උපාංග ඇටසැකිල්ලට අස්ථි 126ක්ද අයත් වේ."),
        q("මිනිස් අක්ෂක ඇටසැකිල්ලට (Axial Skeleton) අයත් වන මුළු අස්ථි සංඛ්‍යාව කීයද?", "අස්ථි 80කි", "අස්ථි 126කි", "අස්ථි 206කි", "අස්ථි 60කි", "කපාලය, කශේරුකා තීරුව, උරෝස්ථිය සහ ඉළඇට අක්ෂක ඇටසැකිල්ලේ අස්ථි 80 සාදයි."),
        q("මිනිස් සිරුරේ උපාංග ඇටසැකිල්ලට (Appendicular Skeleton) අයත් වන අස්ථි සංඛ්‍යාව කීයද?", "අස්ථි 126කි", "අස්ථි 80කි", "අස්ථි 206කි", "අස්ථි 100කි", "උර මේඛලාව, බාහු, ශ්‍රෝණි මේඛලාව සහ පාදවල අස්ථි උපාංග ඇටසැකිල්ලට අයත් වේ."),
        q("මිනිස් කශේරුකා තීරුවේ (කොඳු ඇට පෙළේ) අඩංගු මුළු කශේරුකා සංඛ්‍යාව කීයද?", "කශේරුකා 33කි", "කශේරුකා 24කි", "කශේරුකා 12කි", "කශේරුකා 40කි", "ග්‍රීව 7, උරස් 12, කටී 5, ත්‍රිකාස්ථි 5 (බද්ධ වූ), අනුත්‍රිකාස්ථි 4 (බද්ධ වූ) වශයෙන් කශේරුකා 33ක් ඇත."),
        q("මිනිසාගේ බෙල්ල ප්‍රදේශයේ පිහිටා ඇති ග්‍රීව කශේරුකා (Cervical vertebrae) සංඛ්‍යාව කීයද?", "කශේරුකා 7කි", "කශේරුකා 12කි", "කශේරුකා 5කි", "කශේරුකා 10කි", "ක්ෂීරපායීන්ගේ බෙල්ලේ ග්‍රීව කශේරුකා 7ක් පිහිටන අතර පළමු වැන්න ඇට්ලස්ද දෙවැන්න ඇක්සිස්ද වේ."),
        q("හිස්කබල රඳවාගෙන සිටින පළමුවන ග්‍රීව කශේරුකාව හඳුන්වන විශේෂ නම කුමක්ද?", "ඇට්ලස් කශේරුකාව (Atlas)", "ඇක්සිස් කශේරුකාව", "උරස් කශේරුකාව", "කටී කශේරුකාව", "ඇට්ලස් කශේරුකාව මත හිස්කබල පිහිටා ඇති අතර හිස ඉහළ පහළ නැමීමට එය උපකාරී වේ."),
        q("හිස දෙපසට කරකැවීමේ චලනයට උපකාරී වන දෙවන ග්‍රීව කශේරුකාව කුමක්ද?", "ඇක්සිස් කශේරුකාව (Axis)", "ඇට්ලස් කශේරුකාව", "ත්‍රිකාස්ථිය", "උරෝස්ථිය", "ඇක්සිස් කශේරුකාවේ දන්තමය ප්‍රසරය වටා ඇට්ලස් කශේරුකාව භ්‍රමණය වීමෙන් හිස දෙපසට හැරවිය හැක."),
        q("මිනිස් උරස් කූඩුවේ කශේරුකා තීරුවට සම්බන්ධ වන උරස් කශේරුකා (Thoracic vertebrae) සංඛ්‍යාව කීයද?", "කශේරුකා 12කි", "කශේරුකා 7කි", "කශේරුකා 5කි", "කශේරුකා 2කි", "උරස් කශේරුකා 12 සමග ඉළඇට යුගල 12 පිටුපසින් සන්ධි වේ."),
        q("කොඳු ඇට පෙළේ යටි කොන්ද ප්‍රදේශයේ පිහිටා ඇති වඩාත් විශාල හා ශක්තිමත් කටී කශේරුකා සංඛ්‍යාව කීයද?", "කශේරුකා 5කි", "කශේරුකා 7කි", "කශේරුකා 12කි", "කශේරුකා 4කි", "කටී කශේරුකා (Lumbar vertebrae) 5ක් ඇති අතර ඒවා සිරුරේ බර දැරීමට විශාල කඳකින් යුක්ත වේ."),
        q("මිනිස් උරස් කූඩුවේ අඩංගු මුළු ඉළඇට යුගල සංඛ්‍යාව කීයද?", "ඉළඇට යුගල 12කි (ඉළඇට 24ක්)", "ඉළඇට යුගල 10කි", "ඉළඇට යුගල 7කි", "ඉළඇට යුගල 14කි", "මිනිස් සිරුරේ දෙපසට විහිදුණු ඉළඇට යුගල 12ක් හෙවත් ඉළඇට 24ක් ඇත."),
        q("උරෝස්ථියට (Sternum) ඍජුවම කෘචස්ථි මගින් සම්බන්ධ වන 1 සිට 7 දක්වා වූ ඉළඇට හඳුන්වන්නේ කෙසේද?", "සත්‍ය ඉළඇට (True Ribs)", "අසත්‍ය ඉළඇට", "පා පාවෙන ඉළඇට", "උපාංග ඉළඇට", "පළමු ඉළඇට යුගල 7 තමන්ගේම පර්ශුක කෘචස්ථි මගින් ඍජුවම උරෝස්ථියට සම්බන්ධ වන බැවින් සත්‍ය ඉළඇට නම් වේ."),
        q("උරෝස්ථියට ඍජුව සම්බන්ධ නොවී 7 වන ඉළඇටයේ කෘචස්ථියට සම්බන්ධ වන 8, 9 සහ 10 වන ඉළඇට යුගල හඳුන්වන්නේ කෙසේද?", "අසත්‍ය ඉළඇට (False Ribs)", "සත්‍ය ඉළඇට", "පා පාවෙන ඉළඇට", "අක්ෂක ඉළඇට", "8, 9, 10 ඉළඇට වක්‍රව 7 වන ඉළඇටයට සම්බන්ධ වන බැවින් අසත්‍ය ඉළඇට ලෙස හඳුන්වයි."),
        q("ඉදිරිපසින් කිසිදු අස්ථියකට සම්බන්ධ නොවී මාංශපේශී තුළ නිදහසේ පාවෙන 11 සහ 12 වන ඉළඇට යුගල කුමක්ද?", "පා පාවෙන ඉළඇට (Floating Ribs)", "සත්‍ය ඉළඇට", "අසත්‍ය ඉළඇට", "ස්ථාවර ඉළඇට", "11 හා 12 ඉළඇට ඉදිරිපසින් නිදහස්ව පිහිටන අතර වකුගඩු ආවරණය කර ආරක්ෂා කරයි."),
        q("මිනිස් සිරුරේ උරස් කුහරයේ මධ්‍යයේ ඉදිරිපසින් පිහිටා ඇති පැතලි අස්ථිය කුමක්ද?", "උරෝස්ථිය (Sternum)", "අක්ෂකස්ථිය", "අංශ ඵලකය", "කලවාස්ථිය", "උරෝස්ථිය හදවත හා පෙනහළු ආරක්ෂා කරන උරස් කූඩුවේ ඉදිරිපස කේන්ද්‍රීය අස්ථියයි."),
        q("මිනිස් සිරුරේ උර මේඛලාව (Pectoral Girdle) සමන්විත වන අස්ථි යුගල දෙක මොනවාද?", "අක්ෂකස්ථිය (Clavicle) සහ අංශ ඵලකය (Scapula)", "ප්‍රගණ්ඩාස්ථිය සහ අරාස්ථිය", "උකුල් ඇටය සහ කලවාස්ථිය", "උරෝස්ථිය සහ කශේරුකාව", "කරපට අස්ථිය (Clavicle) සහ පිටුපස ත්‍රිකෝණාකාර අංශ ඵලකය (Scapula) එක්ව උර මේඛලාව තනයි."),
        q("මිනිසාගේ උඩු බාහුවේ (උරහිසේ සිට වැලමිට දක්වා) පිහිටා ඇති තනි දිගු අස්ථිය කුමක්ද?", "ප්‍රගණ්ඩාස්ථිය (Humerus)", "අරාස්ථිය", "අන්වරාස්ථිය", "කලවාස්ථිය", "ප්‍රගණ්ඩාස්ථිය උරහිස් සන්ධියේ සිට වැලමිට සන්ධිය දක්වා විහිදෙන දිගු අස්ථියයි."),
        q("මිනිසාගේ පෙරබාහුවේ (වැලමිටේ සිට මැණික්කටුව දක්වා) මහපටැඟිල්ල දෙසින් පිහිටි අස්ථිය කුමක්ද?", "අරාස්ථිය (Radius)", "අන්වරාස්ථිය", "ප්‍රගණ්ඩාස්ථිය", "අක්ෂකස්ථිය", "අරාස්ථිය මහපටැඟිල්ල පැත්තේ පිහිටන අතර අත කරකැවීමේදී අන්වරාස්ථිය මතින් ගමන් කරයි."),
        q("මිනිසාගේ පෙරබාහුවේ සුලැඟිල්ල (කුඩා ඇඟිල්ල) දෙසින් පිහිටා ඇති දිගු අස්ථිය කුමක්ද?", "අන්වරාස්ථිය (Ulna)", "අරාස්ථිය", "ප්‍රගණ්ඩාස්ථිය", "ජානුවස්ථිය", "අන්වරාස්ථිය වැලමිට සන්ධියේදී ඔලෙක්‍රැනන් ප්‍රසරය සාදන ප්‍රධාන අස්ථියයි."),
        q("මිනිස් අතක මැණික්කටුව සෑදීම සඳහා පේළි දෙකකට සකස් වී ඇති කුඩා අස්ථි (Carpals) සංඛ්‍යාව කීයද?", "අස්ථි 8කි", "අස්ථි 5කි", "අස්ථි 14කි", "අස්ථි 7කි", "මැණික්කටුවේ කාපල් අස්ථි 8ක් පිහිටන අතර ඒවා ලිස්සන සුළු චලන සඳහා ඉඩ සලසයි."),
        q("මිනිස් අත්ල නිර්මාණය කරන අත්ල අස්ථි (Metacarpals) සංඛ්‍යාව කීයද?", "අස්ථි 5කි", "අස්ථි 8කි", "අස්ථි 14කි", "අස්ථි 10කි", "අත්ලේ ඇඟිලි පහට අනුරූපව මෙටාකාපල් අස්ථි 5ක් පිහිටයි."),
        q("මිනිස් අතක හෝ පාදයක ඇඟිලිවල පිහිටා ඇති ඇඟිලි පුරුක් අස්ථි (Phalanges) මුළු සංඛ්‍යාව කීයද?", "අස්ථි 14කි", "අස්ථි 10කි", "අස්ථි 15කි", "අස්ථි 12කි", "මහපටැඟිල්ලේ පුරුක් 2ක්ද අනෙක් ඇඟිලි හතරේ පුරුක් 3 බැගින්ද (2 + 12 = 14) පිහිටයි."),
        q("මිනිස් සිරුරේ ඇති දිගම, ශක්තිමත්ම සහ බරම තනි අස්ථිය කුමක්ද?", "කලවාස්ථිය (Femur)", "ප්‍රගණ්ඩාස්ථිය", "අන්වස්ථාස්ථිය", "උකුල් ඇටය", "කලවාස්ථිය උකුල් සන්ධියේ සිට දණහිස දක්වා විහිදෙන ශරීරයේ විශාලතම අස්ථියයි."),
        q("දණහිස් සන්ධිය ඉදිරිපසින් පිහිටා ඇති පැතලි ත්‍රිකෝණාකාර දණිස් කටුව හඳුන්වන විද්‍යාත්මක නම කුමක්ද?", "ජානුවස්ථිය (Patella)", "අන්වස්ථාස්ථිය", "බහිස්ස්ථාස්ථිය", "ත්‍රිකාස්ථිය", "ජානුවස්ථිය සෙසමොයිඩ් අස්ථියක් වන අතර දණහිස් සන්ධිය ආරක්ෂා කරයි."),
        q("මිනිසාගේ කෙණ්ඩ ප්‍රදේශයේ පිහිටි ශරීරයේ බර දරන ප්‍රධාන විශාල අස්ථිය කුමක්ද?", "අන්වස්ථාස්ථිය (Tibia)", "බහිස්ස්ථාස්ථිය", "කලවාස්ථිය", "අරාස්ථිය", "Tibia හෙවත් අන්වස්ථාස්ථිය දණහිසේ සිට වළලුකර දක්වා සිරුරේ බර දරන ප්‍රධාන අස්ථියයි."),
        q("කෙණ්ඩ ප්‍රදේශයේ අන්වස්ථාස්ථියට සමාන්තරව පිටතින් පිහිටි සිහින් අස්ථිය කුමක්ද?", "බහිස්ස්ථාස්ථිය (Fibula)", "අන්වස්ථාස්ථිය", "ප්‍රගණ්ඩාස්ථිය", "අන්වරාස්ථිය", "Fibula අස්ථිය කෙණ්ඩ පේශි සම්බන්ධ වීමට සහ වළලුකර සන්ධිය ශක්තිමත් කිරීමට උපකාරී වේ."),
        q("මිනිස් පාදයක වළලුකර ප්‍රදේශය සෑදීම සඳහා එකතු වී ඇති ගුල්ඵාස්ථි (Tarsals) සංඛ්‍යාව කීයද?", "අස්ථි 7කි", "අස්ථි 8කි", "අස්ථි 5කි", "අස්ථි 14කි", "වළලුකරෙහි ටාසල් අස්ථි 7ක් පිහිටන අතර විලුඹ අස්ථිය (Calcaneus) ඉන් විශාලතම අස්ථියයි."),
        q("හිස්කබලේ (කපාලයේ) අස්ථි එකිනෙක තදින් බද්ධ වී ඇති චලනය විය නොහැකි සන්ධි වර්ගය කුමක්ද?", "අචල සන්ධි හෙවත් මැහුම් සන්ධි (Sutures)", "පූර්ණ චල සන්ධි", "අසව් සන්ධි", "බෝල සහ කුහර සන්ධි", "කපාල අස්ථි එකිනෙක චලනය නොවන පරිදි තන්තුමය මැහුම් සන්ධි මගින් මොළය ආරක්ෂා කරයි."),
        q("කශේරුකා තීරුවේ කශේරුකා අතර පිහිටා ඇති සීමිත චලනයකට පමණක් ඉඩදෙන සන්ධි වර්ගය කුමක්ද?", "අර්ධ චල සන්ධි (Cartilaginous Joints)", "අචල සන්ධි", "සයිනෝවියල් සන්ධි", "අසව් සන්ධි", "කශේරුකා අතර ඇති කෘචස්ථිමය මඬල මගින් සුළු නම්‍යශීලී බවක් ලබා දෙමින් කම්පන අවශෝෂණය කරයි."),
        q("මිනිස් සිරුරේ සියලු දිශාවලට පුළුල්ව නිදහසේ චලනය විය හැකි පූර්ණ චල සන්ධි හඳුන්වන්නේ කෙසේද?", "සයිනෝවියල් සන්ධි (Synovial Joints)", "අචල සන්ධි", "තන්තුමය සන්ධි", "මැහුම් සන්ධි", "සයිනෝවියල් සන්ධිවල තරල කුහරයක් පවතින බැවින් අස්ථි එකිනෙක ගැටීමකින් තොරව නිදහසේ චලනය වේ."),
        q("සයිනෝවියල් සන්ධියක අස්ථි දෙකේ කෙළවර ආවරණය කරමින් ඝර්ෂණය අවම කරන පටකය කුමක්ද?", "සන්ධි කෘචස්ථිය (Articular Cartilage)", "අස්ථි පටකය", "මේද පටකය", "කණ්ඩරාව", "සිනිඳු සන්ධි කෘචස්ථිය මගින් චලනය වීමේදී අස්ථි ගෙවී යාම වළක්වයි."),
        q("සයිනෝවියල් සන්ධි කුහරය තුළ ඇති ඝර්ෂණය වළක්වන ලිහිසි තරලය කුමක්ද?", "සයිනෝවියල් තරලය (Synovial Fluid)", "ප්ලාස්මාව", "වසා තරලය", "ශ්ලේෂ්මලය", "සයිනෝවියල් පටලයෙන් ශ්‍රාවය වන සයිනෝවියල් තරලය කෘචස්ථි පෝෂණය කරමින් ලිහිසි තෙලක් මෙන් ක්‍රියා කරයි."),
        q("සන්ධියකදී එක් අස්ථියක් තවත් අස්ථියකට තදින් සම්බන්ධ කර රඳවා තබන ප්‍රත්‍යාස්ථ තන්තුමය පටකය කුමක්ද?", "බන්ධනිය (Ligament)", "කණ්ඩරාව (Tendon)", "කාටිලේජය", "පේශි තන්තුව", "බන්ධනී (Ligaments) මගින් අස්ථි එකිනෙක බැඳ තබමින් සන්ධියේ ස්ථායීතාව ආරක්ෂා කරයි."),
        q("මාංශපේශියක් අස්ථියකට තදින් සම්බන්ධ කර චලනය ඇති කිරීමට දායක වන ශක්තිමත් පටකය කුමක්ද?", "කණ්ඩරාව (Tendon)", "බන්ධනිය", "සයිනෝවියල් පටලය", "ස්නායුව", "කණ්ඩරා (Tendons) මගින් පේශි හැකිලීමේදී ඇතිවන බලය අස්ථිය වෙත සම්ප්‍රේෂණය කරයි."),
        q("උරහිස් සන්ධිය සහ උකුල් සන්ධිය අයත් වන්නේ කුමන සයිනෝවියල් සන්ධි වර්ගයටද?", "බෝල සහ කුහර සන්ධි (Ball and Socket Joint)", "අසව් සන්ධි", "කක්ෂ සන්ධි", "ලිස්සන සන්ධි", "බෝල සහ කුහර සන්ධි මගින් අංශක 360ක පමණ පුළුල් වෘත්තාකාර චලනයන් සඳහා ඉඩ සලසයි."),
        q("වැලමිට සන්ධිය සහ දණහිස් සන්ධිය මෙන් එක් තලයක පමණක් නැමීමට සහ දිගහැරීමට ඉඩදෙන සන්ධි වර්ගය කුමක්ද?", "අසව් සන්ධි (Hinge Joint)", "බෝල සහ කුහර සන්ධි", "කක්ෂ සන්ධි", "සෑදල සන්ධි", "දොරක අසව්වක් මෙන් එක් දිශාවකට පමණක් චලනය වන සන්ධි අසව් සන්ධි නම් වේ."),
        q("ඇට්ලස් සහ ඇක්සිස් කශේරුකා අතර පවතින හිස දෙපසට කරකැවීමට ඉඩ සලසන සන්ධි වර්ගය කුමක්ද?", "කක්ෂ සන්ධි හෙවත් කරකැවෙන සන්ධි (Pivot Joint)", "අසව් සන්ධි", "බෝල සහ කුහර සන්ධි", "ලිස්සන සන්ධි", "කක්ෂ සන්ධියකදී එක් අස්ථියක් අනෙක් අස්ථියේ වලල්ලක් වැනි ව්‍යුහයක් තුළ භ්‍රමණය වේ."),
        q("අතේ මැණික්කටු අස්ථි සහ පාදයේ වළලුකර අස්ථි අතර පවතින පැතලි මතුපිටවල් ලිස්සා යන සන්ධි වර්ගය කුමක්ද?", "ලිස්සන සන්ධි (Gliding Joint)", "අසව් සන්ධි", "බෝල සහ කුහර සන්ධි", "කක්ෂ සන්ධි", "ලිස්සන සන්ධි මගින් අස්ථි එකිනෙක මත සුළු වශයෙන් ලිස්සා යාමට ඉඩ ලබා දෙයි."),
        q("මිනිසාගේ මහපටැඟිල්ලේ පාදමේ පිහිටා ඇති විශේෂිත ද්වි-අක්ෂීය චලන සන්ධි වර්ගය කුමක්ද?", "සෑදල සන්ධිය (Saddle Joint)", "අසව් සන්ධිය", "කක්ෂ සන්ධිය", "අචල සන්ධිය", "මහපටැඟිල්ල අනෙක් ඇඟිලිවලට විරුද්ධව තැබීමට හැකි වී ඇත්තේ සෑදල සන්ධිය නිසාය."),
        q("මිනිස් සිරුරේ බරින් 40% - 50% ක් පමණ නියෝජනය කරන ප්‍රධාන පටක වර්ගය කුමක්ද?", "මාංශපේශී පටකය", "අස්ථි පටකය", "මේද පටකය", "සම්බන්ධක පටකය", "මිනිස් සිරුරේ විවිධ චලනයන් හා කාර්යයන් සඳහා පේශි පටක විශාල ස්කන්ධයක් දරයි."),
        q("අපගේ කැමැත්ත පරිදි (හිතාමතා) චලනය කළ හැකි අස්ථි පද්ධතියට සම්බන්ධ වී ඇති පේශි වර්ගය කුමක්ද?", "සැකිලි පේශි හෙවත් ඓච්ඡික පේශි", "සිනිඳු පේශි", "හෘත් පේශිය", "අනෛච්ඡික පේශි", "සැකිලි පේශි අපගේ මස්තිෂ්කයේ පාලනය යටතේ ක්‍රියාත්මක වන ඉරි සහිත ඓච්ඡික පේශි වේ."),
        q("ආමාශය, අන්ත්‍ර, රුධිර නාල සහ මුත්‍රාශය වැනි අභ්‍යන්තර අවයව බිත්තිවල පිහිටි අනෛච්ඡික පේශි වර්ගය කුමක්ද?", "සිනිඳු පේශි (Smooth Muscles)", "සැකිලි පේශි", "හෘත් පේශිය", "ඉරි සහිත පේශි", "සිනිඳු පේශි ස්වයංසාධක ස්නායු පද්ධතිය මගින් පාලනය වන ඉරි රහිත තනි න්‍යෂ්ටික පේශි වේ."),
        q("අතු බෙදුණු තන්තු සහිත, තෙහෙට්ටුවට පත් නොවී ජීවිත කාලය පුරාම රිද්මයානුකූලව හැකිලෙන පේශි වර්ගය කුමක්ද?", "හෘත් පේශිය (Cardiac Muscle)", "සැකිලි පේශි", "සිනිඳු පේශි", "ඓච්ඡික පේශි", "හෘද බිත්තියේ පමණක් පිහිටන හෘත් පේශිය කිසි විටෙකත් විවේක නොගෙන ස්වයංක්‍රීයව ස්පන්දනය වේ."),
        q("අතේ වැලමිට සන්ධිය නවන විට (Flexion) සංකෝචනය වී කෙටි වන පෙර බාහුවේ ඉදිරිපස පේශිය කුමක්ද?", "බයිසෙප්ස් පේශිය (ද්විශීර්ෂික පේශිය)", "ට්‍රයිසෙප්ස් පේශිය", "ඩෙල්ටොයිඩ් පේශිය", "ට්‍රැපීසියස් පේශිය", "ද්විශීර්ෂික පේශිය සංකෝචනය වන විට වැලමිට සන්ධිය නැමී අත උරහිස දෙසට එසවේ."),
        q("අතේ වැලමිට සන්ධිය දිගහරින විට (Extension) සංකෝචනය වන උඩු බාහුවේ පිටුපස පිහිටි පේශිය කුමක්ද?", "ට්‍රයිසෙප්ස් පේශිය (ත්‍රිශීර්ෂික පේශිය)", "බයිසෙප්ස් පේශිය", "පෙක්ටොරාලිස් පේශිය", "ලැටිසිමස් ඩෝසි", "ත්‍රිශීර්ෂික පේශිය සංකෝචනය වන විට ද්විශීර්ෂික පේශිය ලිහිල් වී අත කෙළින් වේ."),
        q("එකිනෙකට විරුද්ධ දිශාවලට ක්‍රියා කරමින් සන්ධියක සුමට චලනයන් පාලනය කරන පේශි යුගල හඳුන්වන්නේ කෙසේද?", "ප්‍රතිවිරෝධී පේශි යුගල (Antagonistic Pairs)", "සමමිතික පේශි", "අනුබද්ධ පේශි", "සමතාන පේශි", "බයිසෙප්ස් සහ ට්‍රයිසෙප්ස් යනු ප්‍රකට ප්‍රතිවිරෝධී පේශි යුගලයකි."),
        q("දණහිස් සන්ධිය දිගහැරීමට (කකුල කෙළින් කිරීමට) උපකාරී වන කලවා ඉදිරිපස පිහිටි ප්‍රබල පේශි කාණ්ඩය කුමක්ද?", "ක්වාඩ්‍රිසෙප්ස් පේශිය (චතුර් ශීර්ෂික පේශිය)", "හැම්ස්ට්‍රිං පේශි", "කෙණ්ඩ පේශිය (Gastrocnemius)", "ග්ලූටියස් මැක්සිමස්", "ක්වාඩ්‍රිසෙප්ස් මගින් දණහිස දිගහැර පයින් ගැසීම, දිවීම වැනි ක්‍රියා සිදු කරයි."),
        q("දණහිස් සන්ධිය නැවීමට (පාදය පසුපසට නැවීමට) දායක වන කලවා පිටුපස පිහිටි පේශි සමූහය කුමක්ද?", "හැම්ස්ට්‍රිං පේශි (Hamstrings)", "ක්වාඩ්‍රිසෙප්ස්", "සර්ටෝරියස්", "ටිබියාලිස්", "හැම්ස්ට්‍රිං පේශි සංකෝචනය වන විට දණහිස නැමී පාදය පසුපසට ඇදේ."),
        q("උරහිස වටා පිහිටා ඇති, අත පැත්තට එසවීමට (Abduction) උපකාරී වන ත්‍රිකෝණාකාර පේශිය කුමක්ද?", "ඩෙල්ටොයිඩ් පේශිය (Deltoid)", "ට්‍රැපීසියස්", "පෙක්ටොරාලිස් මේජර්", "ග්ලූටියස්", "ඩෙල්ටොයිඩ් පේශිය උරහිස් සන්ධිය ආවරණය කරමින් අත විවිධ දිශාවලට එසවීමට උපකාරී වේ."),
        q("මිනිස් සිරුරේ තට්ටම් ප්‍රදේශයේ පිහිටා ඇති ශරීරයේ විශාලතම තනි මාංශපේශිය කුමක්ද?", "ග්ලූටියස් මැක්සිමස් (Gluteus maximus)", "සර්ටෝරියස්", "ක්වාඩ්‍රිසෙප්ස්", "ලැටිසිමස් ඩෝසි", "ග්ලූටියස් මැක්සිමස් ශරීරය කෙළින් තබා ගැනීමට සහ ඇවිදීමට, පඩිපෙළ නැගීමට අත්‍යවශ්‍ය වේ."),
        q("මිනිස් සිරුරේ කලවය හරහා ඇදෙන ශරීරයේ දිගම මාංශපේශිය කුමක්ද?", "සර්ටෝරියස් පේශිය (Sartorius)", "ග්ලූටියස් මැක්සිමස්", "බයිසෙප්ස්", "ගැස්ට්‍රොක්නීactionමියස්", "සර්ටෝරියස් (දරන්නාගේ පේශිය) උකුලේ සිට දණහිස දක්වා ඇදී යන දිගම පේශියයි."),
        q("පේශියේ දිග වෙනස් නොවී ආතතිය පමණක් වැඩිවන සංකෝචන වර්ගය (උදා. බිත්තියක් තල්ලු කිරීම) කුමක්ද?", "සමමිතික සංකෝචනය (Isometric Contraction)", "සමතාන සංකෝචනය", "සමචාලක සංකෝචනය", "අසමමිතික සංකෝචනය", "Isometric ව්‍යායාමවලදී සන්ධි චලනයක් සිදුනොවන නමුත් පේශි ආතතිය ඉහළ යයි."),
        q("පේශියේ දිග වෙනස් වෙමින් (කෙටි වෙමින් හෝ දිගු වෙමින්) බරක් චලනය කරන සංකෝචන වර්ගය කුමක්ද?", "සමතාන සංකෝචනය (Isotonic Contraction)", "සමමිතික සංකෝචනය", "ස්ථිතික සංකෝචනය", "නිෂ්ක්‍රීය සංකෝචනය", "Isotonic සංකෝචනයේදී Concentric (කෙටිවීම) සහ Eccentric (දිගුවීම) ලෙස අදියර දෙකක් ඇත."),
        q("දැඩි ව්‍යායාමයකදී මාංශපේශීවලට ඔක්සිජන් ප්‍රමාණවත් නොවූ විට නිර්වායු ශ්වසනය නිසා පේශිවල තැන්පත් වන අම්ලය කුමක්ද?", "ලැක්ටික් අම්ලය (Lactic Acid)", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "සිට්‍රික් අම්ලය", "ඇසිටික් අම්ලය", "ලැක්ටික් අම්ලය එකතු වීම නිසා මාංශපේශී තෙහෙට්ටුව සහ වේදනාව (Cramp) හටගනී."),
        q("දැඩි ව්‍යායාමයකින් පසු තැන්පත් වූ ලැක්ටික් අම්ලය ඉවත් කර පේශි යථා තත්ත්වයට පත් කිරීමට අවශ්‍ය වන අතිරේක ඔක්සිජන් ප්‍රමාණය හඳුන්වන්නේ කෙසේද?", "ඔක්සිජන් ණය (Oxygen Debt)", "ජෛව ධාරිතාව", "ශ්වසන පරිමාව", "පාදස්ථ ඔක්සිජන්", "ව්‍යායාමයෙන් පසුවද වේගයෙන් හුස්ම ගන්නේ ඔක්සිජන් ණය පියවා ලැක්ටික් අම්ලය බිඳහෙළීමටයි."),
        q("මිනිස් හෘදයේ අභ්‍යන්තර කුටීර සංඛ්‍යාව කීයද?", "කුටීර 4කි (කර්ණිකා 2ක් සහ කෝෂිකා 2ක්)", "කුටීර 2කි", "කුටීර 3කි", "කුටීර 6කි", "මිනිස් හෘදය ඉහළින් කර්ණිකා දෙකකින්ද පහළින් කෝෂිකා දෙකකින්ද සමන්විත වේ."),
        q("හෘදයේ කුටීර අතුරින් මුළු සිරුර පුරාම රුධිරය පොම්ප කිරීම සඳහා වඩාත්ම ඝනකම් පේශි බිත්තියක් සහිත කුටීරය කුමක්ද?", "වම් කෝෂිකාව (Left Ventricle)", "දකුණු කෝෂිකාව", "වම් කර්ණිකාව", "දකුණු කර්ණිකාව", "වම් කෝෂිකාව මහා ධමනිය ඔස්සේ මුළු සිරුරටම අධි පීඩනයෙන් රුධිරය පොම්ප කරන බැවින් එහි බිත්තිය ඉතා ඝනය."),
        q("දකුණු කර්ණිකාව සහ දකුණු කෝෂිකාව අතර රුධිරය ආපසු ගලායාම වළක්වන කපාටය කුමක්ද?", "ත්‍රිතුණ්ඩ කපාටය (Tricuspid Valve)", "ද්විතුණ්ඩ කපාටය", "මහා ධමනි කපාටය", "පුප්ඵුසීය කපාටය", "ත්‍රිතුණ්ඩ කපාටය තුඩු 3කින් යුක්ත වන අතර දකුණු පැත්තේ රුධිර ගමන පාලනය කරයි."),
        q("වම් කර්ණිකාව සහ වම් කෝෂිකාව අතර පිහිටා ඇති මයිට්‍රල් කපාටය ලෙසද හඳුන්වන කපාටය කුමක්ද?", "ද්විතුණ්ඩ කපාටය (Bicuspid / Mitral Valve)", "ත්‍රිතුණ්ඩ කපාටය", "අඩසඳ කපාටය", "පුප්ඵුසීය කපාටය", "ද්විතුණ්ඩ කපාටය මගින් ඔක්සිජන් සහිත රුධිරය වම් කර්ණිකාවේ සිට වම් කෝෂිකාවට ගලායාම තනි දිශාවකට පාලනය කරයි."),
        q("මහා ධමනිය සහ පුප්ඵුසීය ධමනිය ආරම්භයේ පිහිටා ඇති රුධිරය හෘදයට ආපසු ඒම වළක්වන කපාට මොනවාද?", "අඩසඳ කපාට (Semilunar Valves)", "ද්විතුණ්ඩ කපාට", "ත්‍රිතුණ්ඩ කපාට", "කර්ණික කපාට", "කෝෂිකා ලිහිල් වීමේදී රුධිරය ආපසු කෝෂිකා තුළට ගලා ඒම અඩසඳ කපාට මගින් වළක්වයි."),
        q("හෘදයේ දකුණු කෝෂිකාවේ සිට පෙනහළු වෙත ඔක්සිජන් විරහිත රුධිරය රැගෙන යන එකම ධමනිය කුමක්ද?", "පුප්ඵුසීය ධමනිය (Pulmonary Artery)", "මහා ධමනිය", "කරෝටික ධමනිය", "අක්මා ධමනිය", "සාමාන්‍යයෙන් ධමනිවල ඔක්සිජන් සහිත රුධිරය ගලා ගියද පුප්ඵුසීය ධමනියේ ගලා යන්නේ ඔක්සිජන් අඩු රුධිරයයි."),
        q("පෙනහළුවල සිට ඔක්සිජනීකෘත පිරිසිදු රුධිරය හෘදයේ වම් කර්ණිකාව වෙත රැගෙන එන රුධිර නාලය කුමක්ද?", "පුප්ඵුසීය ශිරා (Pulmonary Veins)", "උත්තර මහා ශිරාව", "අධර මහා ශිරාව", "මහා ධමනිය", "පුප්ඵුසීය ශිරා හතර මගින් පෙනහළුවලින් ඔක්සිජන් සපිරි රුධිරය හෘදය වෙත ගෙන එයි."),
        q("හෘදයේ වම් කෝෂිකාවේ සිට ශරීරයේ සියලුම පටක වෙත ඔක්සිජන් සහිත රුධිරය බෙදාහරින ප්‍රධානතම විශාල ධමනිය කුමක්ද?", "මහා ධමනිය (Aorta)", "පුප්ඵුසීය ධමනිය", "කරෝටික ධමනිය", "වෘක්කීය ධමනිය", "මහා ධමනිය ශරීරයේ විශාලතම ධමනිය වන අතර එයින් ප්‍රධාන ධමනි ශාඛා බෙදී යයි."),
        q("හෘද පේශියටම රුධිරය සහ ඔක්සිජන් සපයන විශේෂිත ධමනි පද්ධතිය කුමක්ද?", "කිරීටක ධමනි (Coronary Arteries)", "මහා ධමනිය", "පුප්ඵුසීය ධමනි", "කරෝටික ධමනි", "කිරීටක ධමනි අවහිර වීමෙන් හෘද පේශියට රුධිරය නොලැබී හෘදයාබාධ (Heart Attack) ඇතිවේ."),
        q("රුධිර නාල වර්ග අතරින් රුධිරය සහ සිරුරේ සෛල අතර ද්‍රව්‍ය හුවමාරුව සිදුවන තනි සෛල ස්ථරයකින් යුත් සියුම් නාල මොනවාද?", "රුධිර කේශනාලිකා (Capillaries)", "ධමනි", "ශිරා", "ධමනිකා", "කේශනාලිකා බිත්ති ඉතා තුනී බැවින් විසරණය මගින් වායු, පෝෂක හා අපද්‍රව්‍ය පහසුවෙන් හුවමාරු වේ."),
        q("ශිරා තුළ රුධිරය ගලායාමේදී රුධිරය ආපසු පසුපසට ගැලීම වැළැක්වීම සඳහා ශිරා තුළ පිහිටා ඇති විශේෂ ව්‍යුහය කුමක්ද?", "කපාට (Valves)", "ඝන බිත්ති", "ඉහළ පීඩනය", "ප්‍රත්‍යාස්ථ පටක", "ශිරාවල රුධිර පීඩනය අඩු බැවින් රුධිරය හදවත දෙසට පමණක් ගලා යාමට අභ්‍යන්තර කපාට පිහිටයි."),
        q("නිරෝගී වැඩිහිටියෙකුගේ සාමාන්‍ය ප්‍රශස්ත රුධිර පීඩන අගය රසදිය මිලිමීටර් කීයක් ලෙස සැලකේද?", "120/80 mmHg", "140/90 mmHg", "100/60 mmHg", "160/100 mmHg", "සිස්ටොලික් පීඩනය 120 mmHg සහ ඩයස්ටොලික් පීඩනය 80 mmHg සාමාන්‍ය අගයයි."),
        q("රුධිර පීඩනය මැනීම සඳහා වෛද්‍යවරුන් භාවිත කරන සම්මත උපකරණය කුමක්ද?", "ස්ෆිග්මෝමනෝමීටරය (Sphygmomanometer)", "ස්ටෙතස්කෝපය", "ස්පයිරෝමීටරය", "තර්මෝමීටරය", "ස්ෆිග්මෝමනෝමීටරය මගින් බාහුවේ බ්‍රැකියල් ධමනියේ පීඩනය මනිනු ලබයි."),
        q("විවේකී සුවයෙන් පසුවන සාමාන්‍ය වැඩිහිටියෙකුගේ මිනිත්තුවකට හෘද ස්පන්දන වේගය (ස්පන්දන අනුපාතය) කීයද?", "මිනිත්තුවට වාර 60 සිට 80 දක්වා", "මිනිත්තුවට වාර 30 සිට 40 දක්වා", "මිනිත්තුවට වාර 120 සිට 140 දක්වා", "මිනිත්තුවට වාර 10 සිට 20 දක්වා", "සාමාන්‍ය විවේකී හෘද ස්පන්දන වේගය 72 bpm පමණ වේ."),
        q("ක්‍රමවත් ලෙස දීර්ඝ කාලයක් විඳදරාගැනීමේ ක්‍රීඩාවල නිරත වූ ක්‍රීඩකයෙකුගේ විවේකී හෘද ස්පන්දන වේගය සාමාන්‍ය අයට වඩා අඩු වීම (උදා. 45-55 bpm) හඳුන්වන්නේ කෙසේද?", "ක්‍රීඩා හෘදය හෙවත් බ්‍රැඩිකාර්ඩියාව (Athletic Bradycardia)", "ටැකිකාර්ඩියාව", "අධික රුධිර පීඩනය", "හෘද අකර්මණ්‍යතාව", "පුහුණුව ලත් ක්‍රීඩකයෙකුගේ හෘදයේ පහර පරිමාව (Stroke Volume) වැඩි බැවින් අඩු ස්පන්දන ගණනකින් වැඩි රුධිරයක් පොම්ප කරයි."),
        q("මිනිස් රුධිරයේ ද්‍රවමය කොටස වන රුධිර ප්ලාස්මාව රුධිර පරිමාවෙන් කොපමණ ප්‍රතිශතයක් ගනීද?", "ආසන්න වශයෙන් 55%ක්", "ආසන්න වශයෙන් 45%ක්", "ආසන්න වශයෙන් 90%ක්", "ආසන්න වශයෙන් 10%ක්", "රුධිරයේ 55%ක් ප්ලාස්මාව වන අතර ඉතිරි 45% රුධිර සෛල වේ."),
        q("මිනිස් රතු රුධිර සෛලවල (RBC) ආසන්න සාමාන්‍ය ආයු කාලය දින කීයද?", "දින 120ක් පමණ", "දින 10ක් පමණ", "වසර 5ක්", "දින 30ක් පමණ", "රතු රුධිර සෛල දින 120කට පසු ප්ලීහාව සහ අක්මාව තුළදී විනාශ කර ප්‍රතිචක්‍රීකරණය කෙරේ."),
        q("පරිණත මිනිස් රතු රුධිරාණුවල න්‍යෂ්ටියක් නොපිහිටීමේ ඇති වැදගත් ජීව විද්‍යාත්මක වාසිය කුමක්ද?", "හිමොග්ලොබින් වැඩි ප්‍රමාණයක් රඳවාගෙන වැඩි ඔක්සිජන් පරිමාවක් ගෙන යාමට හැකිවීම", "සෛලය විශාල වීම", "සෛල විභේදනය වේගවත් වීම", "ජීවත් වන කාලය වැඩිවීම", "න්‍යෂ්ටිය නොමැති වීම නිසා රතු රුධිරාණුවේ ද්වි-අවතල හැඩය ලැබී වැඩි මතුපිට වර්ගඵලයක් හා හිමොග්ලොබින් ධාරිතාවක් ලැබේ."),
        q("ශරීරයට ඇතුළු වන රෝගකාරක විෂබීජ භක්ෂණය කිරීම (Phagocytosis) සහ ප්‍රතිදේහ නිපදවීම සිදුකරන රුධිර සෛල වර්ගය කුමක්ද?", "සුදු රුධිර සෛල (WBC)", "රතු රුධිර සෛල", "රුධිර පට්ටිකා", "ප්ලාස්මා සෛල පමණක්", "සුදු රුධිර සෛල ශරීරයේ ආරක්ෂක හමුදාව ලෙස ක්‍රියා කරමින් ප්‍රතිශක්තිය ලබා දෙයි."),
        q("තුවාලයකදී රුධිරය කැටි ගැසීම ආරම්භ කිරීම සඳහා අත්‍යවශ්‍ය වන සෛල ඛණ්ඩිකා මොනවාද?", "රුධිර පට්ටිකා (Platelets / Thrombocytes)", "එරිත්‍රොසයිට", "නියුට්‍රොෆිල", "ලිම්ෆොසයිට", "රුධිර පට්ටිකා තුවාල වූ ස්ථානයට එකතු වී ත්‍රොම්බොප්ලාස්ටින් මුදාහරිමින් රුධිර කැටිය සාදයි."),
        q("ABO රුධිර වර්ගීකරණ පද්ධතියේ 'සර්වත්‍ර දායකයා' (ඕනෑම අයෙකුට රුධිරය දිය හැකි) ලෙස හඳුන්වන්නේ කුමන රුධිර ඝනයද?", "O සෘණ (O Negative) රුධිර ඝනය", "AB ධන රුධිර ඝනය", "A ධන රුධිර ඝනය", "B සෘණ රුධිර ඝනය", "O සෘණ රුධිර සෛල මතුපිට A, B හෝ Rh ප්‍රතිදේහජනක නොමැති බැවින් ප්‍රතික්ෂේප වීමකින් තොරව ඕනෑම අයෙකුට ලබාදිය හැක."),
        q("ABO රුධිර පද්ධතියේ 'සර්වත්‍ර ප්‍රතිග්‍රාහකයා' (ඕනෑම අයෙකුගෙන් රුධිරය ලබාගත හැකි) ලෙස හඳුන්වන්නේ කුමන රුධිර ගණයද?", "AB ධන (AB Positive) රුධිර ඝනය", "O සෘණ රුධිර ඝනය", "A සෘණ රුධිර ඝනය", "B ධන රුධිර ඝනය", "AB ධන රුධිර ප්ලාස්මාවේ ප්‍රතිදේහ නොමැති බැවින් ඕනෑම රුධිර ඝනයක් ආරක්ෂිතව ලබාගත හැක."),
        q("මිනිස් ශ්වසන පද්ධතියේ වාතය සහ රුධිරය අතර වායු හුවමාරුව (O2 සහ CO2) සිදුවන ප්‍රධානතම ක්‍රියාකාරී ව්‍යුහය කුමක්ද?", "වායු කෝෂ හෙවත් ඇල්වියෝල (Alveoli)", "ශ්වාසනාලය", "ග්‍රසනිකාව", "ස්වරාලය", "පෙනහළුවල ඇති මිලියන 300කට අධික ඇල්වියෝලවල තනි සෛල බිත්ති හරහා වායු විසරණය වේ."),
        q("ආශ්වාසයේදී (හුස්ම ඇතුළට ගැනීමේදී) මහා ප්‍රාචීරයට (Diaphragm) සහ උරස් කුහරයට සිදුවන වෙනස කුමක්ද?", "මහා ප්‍රාචීරය සංකෝචනය වී පහත් වීම සහ උරස් කුහරයේ පරිමාව වැඩිවීම", "මහා ප්‍රාචීරය ඉහළට එසවීම", "උරස් කුහරයේ පරිමාව අඩුවීම", "පෙනහළු හැකිලීම", "ප්‍රාචීරය පහත් වී උරස් පරිමාව වැඩි වන විට පෙනහළු තුළ පීඩනය අඩු වී පිටත වාතය ඇතුළට ගලා එයි."),
        q("ප්‍රශ්වාසයේදී (හුස්ම පිටකිරීමේදී) පෙනහළුවලින් වාතය පිටවීමට හේතුවන භෞතික සාධකය කුමක්ද?", "ප්‍රාචීරය ලිහිල් වී ඉහළට එසවීමෙන් උරස් කුහරයේ පීඩනය වායුගෝල පීඩනයට වඩා වැඩිවීම", "උරස් කුහරයේ පරිමාව වැඩිවීම", "ඉළඇට පිටතට එසවීම", "පෙනහළු තුළ පීඩනය අඩුවීම", "ලිහිල් වීමේදී උරස් කුහරයේ පීඩනය වැඩි වී වාතය පිටතට තල්ලු වේ."),
        q("සාමාන්‍ය සන්සුන් හුස්ම ගැනීමේදී එක් වරකට ඇතුළු කරගන්නා හෝ පිටකරන වායු පරිමාව හඳුන්වන නම කුමක්ද?", "උදම් පරිමාව (Tidal Volume)", "ජෛව ධාරිතාව", "ශේෂ පරිමාව", "සම්පූර්ණ පෙනහළු ධාරිතාව", "නිරෝගී වැඩිහිටියෙකුගේ සාමාන්‍ය උදම් පරිමාව මිලිලීටර් 500ක් (500 ml) පමණ වේ."),
        q("උපරිම ආශ්වාසයකින් පසු සම්පූර්ණ බලය යොදා පිටකළ හැකි උපරිම වායු පරිමාව හඳුන්වන්නේ කෙසේද?", "ජෛව ධාරිතාව (Vital Capacity)", "උදම් පරිමාව", "ශේෂ පරිමාව", "අවම ධාරිතාව", "ජෛව ධාරිතාව සාමාන්‍යයෙන් ලීටර් 3.5 සිට 4.5 දක්වා වන අතර පුහුණු ක්‍රීඩකයන් තුළ එය ලීටර් 5-6 දක්වා වැඩි විය හැක."),
        q("පෙනහළු ධාරිතාව සහ ජෛව ධාරිතාව මැනීම සඳහා භාවිත කරනු ලබන උපකරණය කුමක්ද?", "ස්පයිරෝමීටරය (Spirometer)", "ස්ෆිග්මෝමනෝමීටරය", "ස්ටෙතස්කෝපය", "බාරෝමීටරය", "ස්පයිරෝමීටරය මගින් ශ්වසන පරිමා ප්‍රස්තාරගත කර පෙනහළු ක්‍රියාකාරිත්වය තක්සේරු කරයි."),
        q("පූර්ණ ප්‍රශ්වාසයකින් පසුවද පෙනහළු හැකිලී යාම වළක්වමින් පෙනහළු තුළ නිතරම ඉතිරිව පවතින වායු පරිමාව කුමක්ද?", "ශේෂ පරිමාව (Residual Volume)", "උදම් පරිමාව", "ජෛව ධාරිතාව", "අතිරේක පරිමාව", "ශේෂ පරිමාව (1200 ml පමණ) නිසා පෙනහළු ඇල්වියෝල සම්පූර්ණයෙන්ම කඩා වැටීමකින් තොරව විවෘතව පවතී."),
        q("මිනිස් මොළයේ විශාලතම කොටස වන බුද්ධිය, තර්කනය, මතකය සහ ඓච්ඡික චලන පාලනය කරන ප්‍රදේශය කුමක්ද?", "මස්තිෂ්කය (Cerebrum)", "අනුමස්තිෂ්කය", "සුෂුම්නා ශීර්ෂකය", "හයිපොතලමස", "මස්තිෂ්කය මස්තිෂ්ක අර්ධගෝල දෙකකින් සමන්විත වන අතර සියලුම සවිඥානක ක්‍රියා පාලනය කරයි."),
        q("ශරීරයේ සමබරතාවය, ඉරියව් සහ මාංශපේශී සමායෝජනය නිවැරදිව පාලනය කරන මොළයේ කොටස කුමක්ද?", "අනුමස්තිෂ්කය (Cerebellum)", "මස්තිෂ්කය", "සුෂුම්නා ශීර්ෂකය", "තලමස", "අනුමස්තිෂ්කය මගින් ඇවිදීම, දිවීම, බයිසිකල් පැදීම වැනි ක්‍රියාකාරකම්වලදී සමබරතාව රැකදෙයි."),
        q("හෘද ස්පන්දනය, ශ්වසනය, රුධිර පීඩනය සහ ගිලීම, කැස්ස වැනි වැදගත් අනෛච්ඡික ජීව ක්‍රියා පාලනය කරන මොළයේ කඳ කොටස කුමක්ද?", "සුෂුම්නා ශීර්ෂකය (Medulla Oblongata)", "මස්තිෂ්කය", "අනුමස්තිෂ්කය", "පිටියුටරිය", "සුෂුම්නා ශීර්ෂකයට සිදුවන බරපතළ හානි ක්ෂණික මරණයට හේතු විය හැක."),
        q("උණුසුම් වස්තුවක අත ගැටුණු සැනින් නොදැනුවත්වම අත ඉවතට ඇදගැනීම වැනි ඉක්මන් ස්වයංක්‍රීය අනෛච්ඡික ක්‍රියාවක් හඳුන්වන්නේ කෙසේද?", "ප්‍රතිචාර ක්‍රියාවක් (Reflex Action)", "ඓච්ඡික ක්‍රියාවක්", "සංවේදී ක්‍රියාවක්", "ඉගෙනගත් ක්‍රියාවක්", "ප්‍රතිචාර ක්‍රියා මොළයේ සවිඥානක මැදිහත්වීමකින් තොරව සුෂුම්නාව මගින් ඉතා වේගයෙන් පාලනය වේ."),
        q("ප්‍රතිචාර ක්‍රියාවකදී ස්නායු ආවේගය ගමන් කරන නිවැරදි මාර්ගය (ප්‍රතිචාර චාපය) කුමක්ද?", "ප්‍රතිග්‍රාහකය — සංවේදක නියුරෝනය — අන්තර්බන්ධක නියුරෝනය — චාලක නියුරෝනය — කාර්යකය (පේශිය)", "කාර්යකය — චාලක නියුරෝනය — මොළය — සංවේදක නියුරෝනය", "සංවේදක නියුරෝනය — කාර්යකය — මොළය — ප්‍රතිග්‍රාහකය", "ප්‍රතිග්‍රාහකය — චාලක නියුරෝනය — සංවේදක නියුරෝනය", "ප්‍රතිග්‍රාහකයේ සිට සුෂුම්නාව හරහා ක්ෂණිකව පේශිය වෙත ආවේගය සම්ප්‍රේෂණය වේ."),
        q("මිනිස් සිරුරේ ප්‍රධානම බහිස්ස්‍රාවී ඉන්ද්‍රිය වන වකුගඩුවල මූලික ව්‍යුහාත්මක හා ක්‍රියාකාරී ඒකකය කුමක්ද?", "නෙෆ්‍රෝනය (Nephron)", "නියුරෝනය", "ඇල්වියෝලය", "අක්මා සෛලය", "එක් වකුගඩුවක මිලියනයකට අධික නෙෆ්‍රෝන ප්‍රමාණයක් රුධිරය පෙරා මුත්‍ර නිපදවයි."),
        q("වකුගඩුවේ නෙෆ්‍රෝනය තුළ රුධිරය අධි පීඩනයෙන් පෙරීම (පෙරීම) සිදුවන සුවිශේෂී කේශනාලිකා ගුච්ඡය කුමක්ද?", "ග්ලොමියුරුලස (Glomerulus)", "බෝමන් ප්‍රවාරය", "හෙන්ලේ පුඩුව", "සංග්‍රාහක නාලය", "ග්ලොමියුරුලස තුළ ඇති ඉහළ ජලස්ථිතික පීඩනය නිසා රුධිරයේ ඇති ජලය හා ක්ෂුද්‍ර අණු බෝමන් ප්‍රවාරයට පෙරේ."),
        q("ග්ලොමියුරුලික පෙරනයෙන් ග්ලූකෝස් සහ ඇමයිනෝ අම්ල සම්පූර්ණයෙන්ම නැවත රුධිරයට අවශෝෂණය කරන්නේ නෙෆ්‍රෝනයේ කුමන කොටසේද?", "ප්‍රාථමික සංවලිත නාලිකාව (Proximal Convoluted Tubule)", "හෙන්ලේ පුඩුව", "සංග්‍රාහක නාලය", "ග්ලොමියුරුලස", "නිරෝගී පුද්ගලයෙකුගේ පෙරනයේ ඇති සියලුම ග්ලූකෝස් ප්‍රාථමික නාලිකාවේදී රුධිරයට නැවත උරාගනී."),
        q("නිරෝගී පුද්ගලයෙකුගේ මුත්‍රාවල කිසිසේත්ම අඩංගු නොවිය යුතු සංඝටකයක් වන්නේ කුමක්ද?", "ග්ලූකෝස් සහ රතු රුධිර සෛල", "යූරියා", "යූරික් අම්ලය", "ජලය සහ සෝඩියම්", "මුත්‍රාවල ග්ලූකෝස් තිබීම දියවැඩියා රෝග ලක්ෂණයක් වන අතර රුධිරය තිබීම වකුගඩු ආසාදන ලක්ෂණයකි."),
        q("සිරුරේ අක්මාව මගින් ප්‍රෝටීන් පරිවෘත්තියේදී හැදෙන අධික විෂ සහිත ඇමෝනියා අඩු විෂ සහිත කුමන ද්‍රව්‍යයක් බවට පත් කරයිද?", "යූරියා (Urea)", "යූරික් අම්ලය", "ග්ලූකෝස්", "ඇමයිනෝ අම්ල", "අක්මාව තුළ ඔර්නිතින් චක්‍රය මගින් ඇමෝනියා යූරියා බවට පත් කර වකුගඩු මගින් බැහැර කරයි."),
        q("ක්‍රීඩා පුහුණුව නිසා හෘදයේ පහර පරිමාව (Stroke Volume) වැඩිවීමෙන් සිදුවන වාසිදායක තත්ත්වය කුමක්ද?", "එක් හෘද ස්පන්දනයකින් වැඩි රුධිර පරිමාවක් ශරීර පටක වෙත පොම්ප කිරීමට හැකිවීම", "හෘද ස්පන්දන වේගය අධික ලෙස වැඩිවීම", "රුධිර පීඩනය අනතුරුදායක ලෙස ඉහළ යාම", "රුධිරයේ ඔක්සිජන් අඩුවීම", "පහර පරිමාව වැඩිවීම නිසා හෘදයට අඩු වෙහෙසකින් ශරීරයට අවශ්‍ය රුධිරය සැපයිය හැක.")
    )
}
